-- SIGESTEC Iteracion 1. Ejecutar en esquema Oracle vacío, usuario propio.
CREATE TABLE cliente (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ruc VARCHAR2(11) NOT NULL UNIQUE,razonSocial VARCHAR2(160) NOT NULL,telefono VARCHAR2(255),contacto VARCHAR2(255));
CREATE TABLE tipo_servicio (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR2(255) NOT NULL UNIQUE,descripcion VARCHAR2(255));
CREATE TABLE solicitud (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cliente_id NUMBER NOT NULL REFERENCES cliente(id),tipoServicio_id NUMBER NOT NULL REFERENCES tipo_servicio(id),descripcion VARCHAR2(1200) NOT NULL,observaciones VARCHAR2(1200),fechaRecepcion TIMESTAMP NOT NULL,estado VARCHAR2(255) NOT NULL);
CREATE TABLE cotizacion (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,solicitud_id NUMBER NOT NULL REFERENCES solicitud(id),descripcionTrabajo VARCHAR2(1200) NOT NULL,monto NUMBER(14,2) NOT NULL,observaciones VARCHAR2(1200),estado VARCHAR2(255) NOT NULL,fecha TIMESTAMP NOT NULL,CONSTRAINT ck_cot_monto CHECK(monto>0));
CREATE TABLE orden_compra (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cotizacion_id NUMBER NOT NULL REFERENCES cotizacion(id),numero VARCHAR2(255) NOT NULL UNIQUE,fechaEmision DATE NOT NULL,montoTotal NUMBER(14,2) NOT NULL,nombrePdf VARCHAR2(255),pdf BLOB,CONSTRAINT ck_oc_monto CHECK(montoTotal>0));
CREATE TABLE empleado (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR2(255) NOT NULL,perfil VARCHAR2(255) NOT NULL,activo NUMBER(1) NOT NULL);
CREATE TABLE orden_trabajo (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,solicitud_id NUMBER NOT NULL REFERENCES solicitud(id),tecnico_id NUMBER NOT NULL REFERENCES empleado(id),ssoma_id NUMBER NOT NULL REFERENCES empleado(id),apoyo_id NUMBER REFERENCES empleado(id),estado VARCHAR2(255) NOT NULL,inicio TIMESTAMP,fin TIMESTAMP,lugar VARCHAR2(255),fechaEnvio DATE,aprobadoCliente NUMBER(1),motivoCambio VARCHAR2(500),nombrePt VARCHAR2(255),pt BLOB,nombreIper VARCHAR2(255),iper BLOB,nombreCroquis VARCHAR2(255),croquis BLOB);
CREATE TABLE ats (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ordenTrabajo_id NUMBER NOT NULL REFERENCES orden_trabajo(id),condicionesArea VARCHAR2(2000),peligros VARCHAR2(3000),epp VARCHAR2(3000),herramientas VARCHAR2(2000),etapasJson VARCHAR2(4000),estado VARCHAR2(255) NOT NULL,fechaElaboracion TIMESTAMP NOT NULL);
CREATE TABLE usuario (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR2(255) NOT NULL UNIQUE,password VARCHAR2(100) NOT NULL,nombre VARCHAR2(255) NOT NULL,rol VARCHAR2(255) NOT NULL);
CREATE UNIQUE INDEX uq_cot_solicitud ON cotizacion(solicitud_id);
CREATE UNIQUE INDEX uq_oc_cot ON orden_compra(cotizacion_id);
CREATE UNIQUE INDEX uq_ot_solicitud ON orden_trabajo(solicitud_id);
CREATE UNIQUE INDEX uq_ats_ot ON ats(ordenTrabajo_id);
-- Crear cuentas mediante BCrypt en proceso seguro de aprovisionamiento (NO insertar passwords en texto plano).
-- La autenticacion y los roles de aplicacion se almacenan en 'usuario'; los permisos del esquema Oracle se administran aparte.
